namespace Calc;

/// <summary>
/// Recursive-descent evaluator for 64-bit signed integer expressions.
/// </summary>
/// <remarks>
/// Grammar:
/// <code>
/// expr    := term    (('+' | '-') term)*
/// term    := unary   (('*' | '/' | '%') unary)*
/// unary   := '-' unary | primary
/// primary := NUMBER | '(' expr ')'
/// </code>
/// </remarks>
public ref struct Evaluator
{
    private readonly ReadOnlySpan<byte> _text;
    private int _pos;

    private Evaluator(ReadOnlySpan<byte> text)
    {
        _text = text;
        _pos = 0;
    }

    /// <summary>
    /// Evaluates one expression. Returns <c>false</c> on a syntax error,
    /// division by zero, or 64-bit overflow.
    /// </summary>
    public static bool TryEvaluate(ReadOnlySpan<byte> text, out long value)
    {
        var evaluator = new Evaluator(text);
        try
        {
            value = evaluator.ParseExpr();
            evaluator.SkipWhitespace();
            if (evaluator._pos != text.Length)
            {
                throw new EvaluationException();
            }
            return true;
        }
        catch (Exception ex) when (ex is EvaluationException or OverflowException or DivideByZeroException)
        {
            value = 0;
            return false;
        }
    }

    private long ParseExpr()
    {
        long left = ParseTerm();
        while (true)
        {
            switch (Peek())
            {
                case (byte)'+':
                    _pos++;
                    left = checked(left + ParseTerm());
                    break;
                case (byte)'-':
                    _pos++;
                    left = checked(left - ParseTerm());
                    break;
                default:
                    return left;
            }
        }
    }

    private long ParseTerm()
    {
        long left = ParseUnary();
        while (true)
        {
            switch (Peek())
            {
                case (byte)'*':
                    _pos++;
                    left = checked(left * ParseUnary());
                    break;
                case (byte)'/':
                    _pos++;
                    left = Divide(left, ParseUnary());
                    break;
                case (byte)'%':
                    _pos++;
                    left = Remainder(left, ParseUnary());
                    break;
                default:
                    return left;
            }
        }
    }

    private long ParseUnary()
    {
        if (Peek() == (byte)'-')
        {
            _pos++;
            return checked(-ParseUnary());
        }
        return ParsePrimary();
    }

    private long ParsePrimary()
    {
        byte c = Peek();
        if (c == (byte)'(')
        {
            _pos++;
            long inner = ParseExpr();
            if (Peek() != (byte)')')
            {
                throw new EvaluationException();
            }
            _pos++;
            return inner;
        }
        if (IsDigit(c))
        {
            return ParseNumber();
        }
        throw new EvaluationException();
    }

    private long ParseNumber()
    {
        long result = 0;
        while (_pos < _text.Length && IsDigit(_text[_pos]))
        {
            result = checked((result * 10) + (_text[_pos] - '0'));
            _pos++;
        }
        return result;
    }

    private static long Divide(long dividend, long divisor)
    {
        if (divisor == 0)
        {
            throw new DivideByZeroException();
        }
        return checked(dividend / divisor);
    }

    private static long Remainder(long dividend, long divisor)
    {
        if (divisor == 0)
        {
            throw new DivideByZeroException();
        }
        // long.MinValue % -1 would trap on some platforms; the true remainder is 0.
        return divisor == -1 ? 0 : dividend % divisor;
    }

    /// <summary>Skips whitespace and returns the next byte, or 0 at end of input.</summary>
    private byte Peek()
    {
        SkipWhitespace();
        return _pos < _text.Length ? _text[_pos] : (byte)0;
    }

    private void SkipWhitespace()
    {
        while (_pos < _text.Length && _text[_pos] is (byte)' ' or (byte)'\t')
        {
            _pos++;
        }
    }

    private static bool IsDigit(byte c) => c is >= (byte)'0' and <= (byte)'9';

    private sealed class EvaluationException : Exception;
}

using System.Buffers.Text;
using Calc;

// Deeply nested input recurses deeply; run on a thread with a generous stack.
const int StackSize = 512 * 1024 * 1024;

var worker = new Thread(Run, StackSize);
worker.Start();
worker.Join();
return 0;

static void Run()
{
    byte[] input;
    using (var stdin = Console.OpenStandardInput())
    using (var buffer = new MemoryStream())
    {
        stdin.CopyTo(buffer);
        input = buffer.ToArray();
    }

    using var stdout = new BufferedStream(Console.OpenStandardOutput(), 1 << 16);
    ReadOnlySpan<byte> errorLine = "error\n"u8;
    Span<byte> number = stackalloc byte[24];

    ReadOnlySpan<byte> remaining = input;
    while (!remaining.IsEmpty)
    {
        int newline = remaining.IndexOf((byte)'\n');
        ReadOnlySpan<byte> line = newline < 0 ? remaining : remaining[..newline];
        remaining = newline < 0 ? [] : remaining[(newline + 1)..];

        if (line.Trim(" \t"u8).IsEmpty)
        {
            continue;
        }

        if (Evaluator.TryEvaluate(line, out long value) && Utf8Formatter.TryFormat(value, number, out int written))
        {
            number[written++] = (byte)'\n';
            stdout.Write(number[..written]);
        }
        else
        {
            stdout.Write(errorLine);
        }
    }
}
